S.append(TB(c,B+' · 1','Bảng 17.1: một số lớp giả thường dùng',['Lớp giả','Áp dụng khi','Ví dụ'],[['<code>:link</code>','liên kết <b>chưa</b> được kích hoạt','<code>a:link {color: blue;}</code>'],['<code>:visited</code>','liên kết <b>đã</b> được kích hoạt','<code>a:visited {color: gray;}</code>'],['<code>:hover</code>','<b>di chuột</b> lên phần tử','<code>#home:hover {font-size: 150%;}</code>'],['<code>:active</code>','đang <b>nháy giữ chuột</b> (mở rộng)','<code>a:active {color: red;}</code>'],['<code>:focus</code>','phần tử đang được <b>chọn</b> (mở rộng)','<code>input:focus {border: 2px solid blue;}</code>']],mono=1,note=WARN('Thứ tự khuyến nghị khi viết cho liên kết: <b>link → visited → hover → active</b> (LoVe HAte).')))
